Iterable<CatalogoCupsSeedRow> catalogoCupsSeedRows() sync* {
  final payload = utf8.decode(
    gzip.decode(base64Decode(_cupsGzipBase64.replaceAll(RegExp(r'\s+'), ''))),
  );
  for (final line in const LineSplitter().convert(payload).skip(1)) {
    if (line.trim().isEmpty) continue;
    final parts = line.split('\t');
    yield CatalogoCupsSeedRow(parts[0], parts[1], parts[2]);
  }
}

Iterable<CatalogoCie10SeedRow> catalogoCie10SeedRows() sync* {
  final payload = utf8.decode(
    gzip.decode(base64Decode(_cie10GzipBase64.replaceAll(RegExp(r'\s+'), ''))),
  );
  for (final line in const LineSplitter().convert(payload).skip(1)) {
    if (line.trim().isEmpty) continue;
    final parts = line.split('\t');
    yield CatalogoCie10SeedRow(parts[0], parts[1]);
  }
}

class CatalogoCupsSeedRow {
  const CatalogoCupsSeedRow(this.codigo, this.nombre, this.tipoServicio);

  final String codigo;
  final String nombre;
  final String tipoServicio;
}

class CatalogoCie10SeedRow {
  const CatalogoCie10SeedRow(this.codigo, this.nombre);

  final String codigo;
  final String nombre;
}
